var scriptCode =
  'function showPage(e,name){' +
  'document.querySelectorAll(".page").forEach(function(p){p.classList.remove("active");});' +
  'document.querySelectorAll(".nav").forEach(function(n){n.classList.remove("active");});' +
  'document.getElementById("page-"+name).classList.add("active");' +
  'e.currentTarget.classList.add("active");}' +
  'function initStars(){var sp=document.getElementById("star-picker");if(!sp)return;var stars=sp.querySelectorAll("span");stars.forEach(function(s,i){s.addEventListener("mouseover",function(){stars.forEach(function(x,j){x.classList.toggle("lit",j<=i);});});s.addEventListener("click",function(){s.dataset.selected=1;});});sp.addEventListener("mouseleave",function(){var sel=0;stars.forEach(function(x){if(x.dataset.selected)sel=parseInt(x.dataset.val);});stars.forEach(function(x,j){x.classList.toggle("lit",j<sel);});});}' +
  'document.addEventListener("DOMContentLoaded",initStars);' +
  'function openBirdPopup(){document.getElementById("bird-popup-overlay").classList.add("open");initBirdStars();}function closeBirdPopup(e){if(!e||e.target===document.getElementById("bird-popup-overlay")){document.getElementById("bird-popup-overlay").classList.remove("open");}}function initBirdStars(){var stars=document.querySelectorAll("#bp-star-row .bp-star");var sel=0;stars.forEach(function(s,i){s.onmouseover=function(){stars.forEach(function(x,j){x.classList.toggle("lit",j<=i);});};s.onclick=function(){sel=i+1;stars.forEach(function(x,j){x.classList.toggle("lit",j<sel);});};});document.getElementById("bp-star-row").onmouseleave=function(){stars.forEach(function(x,j){x.classList.toggle("lit",j<sel);});};}function submitBirdReview(){var stars=document.querySelectorAll("#bp-star-row .bp-star");var rating=0;stars.forEach(function(s,i){if(s.classList.contains("lit"))rating=i+1;});var title=document.getElementById("bp-title").value.trim();var body=document.getElementById("bp-body").value.trim();var name=document.getElementById("bp-name").value.trim();if(!rating){alert("Please select a star rating.");return;}if(body.length<10){alert("Please write at least 10 characters.");return;}if(!name){alert("Please enter your name.");return;}var popup=document.getElementById("bird-popup");popup.innerHTML="&#x1F389;Thank you!Your review has been submitted and will appear shortly.";setTimeout(function(){document.getElementById("bird-popup-overlay").classList.remove("open");},2500);}' +
  'function submitReview(){alert("Review submitted! Thank you.");}' +
  'function copyEmbed(){' +
  'var code=document.getElementById("embed-code").textContent;' +
  'if(navigator.clipboard){navigator.clipboard.writeText(code).then(function(){alert("Copied!");});}}';

var birdPopupPage = "<div class=\"page\" id=\"page-birdpopup\"><div style=\"padding:32px 40px;max-width:900px;margin:0 auto\"><h1 style=\"font-size:22px;font-weight:700;margin-bottom:6px\">&#x1F426; Floating Bird Review Button</h1><p style=\"font-size:14px;color:#6d7175;margin-bottom:24px\">A floating bird button appears on every product page after the widget is installed. Clicking it opens an inline review popup — no page redirect needed.</p><div style=\"display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:28px\"><div class=\"card\"><div style=\"font-size:28px;margin-bottom:8px\">&#x1F426;</div><div style=\"font-weight:600;font-size:14px;margin-bottom:4px\">Floating Bird Button</div><p style=\"font-size:13px;color:#6d7175;margin:0\">Fixed to bottom-right of every product page. Bounces gently to attract attention. Shows \"Drop a review!\" tooltip on hover.</p></div><div class=\"card\"><div style=\"font-size:28px;margin-bottom:8px\">&#x1F4DD;</div><div style=\"font-weight:600;font-size:14px;margin-bottom:4px\">Inline Popup Form</div><p style=\"font-size:13px;color:#6d7175;margin:0\">Slides up from the bottom. Customer rates, writes, and submits without leaving the page. POSTs directly to the Rizzz API.</p></div></div><div style=\"font-weight:600;font-size:15px;margin-bottom:12px\">&#x1F3AE; Live Demo — click the bird button</div><div class=\"bird-demo-wrap\"><div class=\"bird-demo-label\">&#x1F6CD;&#xFE0F; This is how the product page looks with the bird button active</div><div style=\"font-size:14px;color:#555;line-height:1.8\"><strong>Air Max Pro Running Shoes</strong><br></br>Premium running shoes engineered for long-distance performance...<br></br><span style=\"color:#f5a623\">&#x2605;&#x2605;&#x2605;&#x2605;&#x2606;</span> 4.3 (142 reviews)</div><div class=\"bird-tooltip\">Drop a review! &#x1F4AC;</div><button class=\"bird-fab\" onclick=\"openBirdPopup()\">&#x1F426;</button></div><div class=\"bird-popup-overlay\" id=\"bird-popup-overlay\" onclick=\"closeBirdPopup(event)\"><div class=\"bird-popup\" id=\"bird-popup\"><div class=\"bp-header\"><div class=\"bp-title\">&#x1F426; Drop a Review</div><button class=\"bp-close\" onclick=\"closeBirdPopup()\">&times;</button></div><div class=\"bp-product\"><div class=\"bp-product-img\">&#x1F45F;</div><div><div style=\"font-weight:600;font-size:14px\">Air Max Pro Running Shoes</div><div style=\"font-size:12px;color:#888;margin-top:2px\">demo-store.myshopify.com</div></div></div><label class=\"bp-label\">Your rating <span style=\"color:#e53e3e\">*</span></label><div class=\"bp-star-row\" id=\"bp-star-row\"><span class=\"bp-star\" data-val=\"1\">&#x2605;</span><span class=\"bp-star\" data-val=\"2\">&#x2605;</span><span class=\"bp-star\" data-val=\"3\">&#x2605;</span><span class=\"bp-star\" data-val=\"4\">&#x2605;</span><span class=\"bp-star\" data-val=\"5\">&#x2605;</span></div><label class=\"bp-label\">Review title</label><input type=\"text\" class=\"bp-input\" id=\"bp-title\" placeholder=\"Summarise your experience\"></input><label class=\"bp-label\">Your review <span style=\"color:#e53e3e\">*</span></label><textarea class=\"bp-input\" id=\"bp-body\" placeholder=\"What did you like or dislike? How was the quality, fit, or performance?\"></textarea><label class=\"bp-label\">Your name <span style=\"color:#e53e3e\">*</span></label><input type=\"text\" class=\"bp-input\" id=\"bp-name\" placeholder=\"e.g. Priya S.\"></input><button class=\"bp-submit\" onclick=\"submitBirdReview()\">Submit Review</button><div class=\"bp-logo\">Powered by <a href=\"#\" style=\"color:#7F77DD;text-decoration:none\">Rizzz community</a></div></div></div><div style=\"font-weight:600;font-size:15px;margin:28px 0 12px\">&#x1F4C4; How it's injected</div><div class=\"card\"><p style=\"font-size:13px;color:#6d7175;margin-bottom:12px\">The bird button is injected by <code style=\"background:#f0eeff;padding:1px 5px;border-radius:3px;font-size:12px\">rizzz-widget.js</code> alongside the review widget. No extra configuration needed — it activates automatically when the widget script tag is installed.</p><div style=\"background:#1e1e2e;color:#cdd6f4;border-radius:8px;padding:14px 16px;font-family:monospace;font-size:12px;line-height:1.8\"><span style=\"color:#6c7086\">// rizzz-widget.js — runs on every product page</span>\n<span style=\"color:#cba6f7\">function</span> <span style=\"color:#89b4fa\">initWithBird</span>() {\n  <span style=\"color:#89b4fa\">mount</span>(reviewContainer);   <span style=\"color:#6c7086\">// renders review list</span>\n  <span style=\"color:#89b4fa\">injectBirdButton</span>(handle); <span style=\"color:#6c7086\">// adds floating bird FAB</span>\n}\n\n<span style=\"color:#6c7086\">// On submit, POSTs directly to Rizzz API:</span>\n<span style=\"color:#89b4fa\">fetch</span>(API + <span style=\"color:#a6e3a1\">\"/reviews\"</span>, {\n  method: <span style=\"color:#a6e3a1\">\"POST\"</span>,\n  body: JSON.<span style=\"color:#89b4fa\">stringify</span>({ shop, handle, rating, title, body, author })\n});</div></div></div></div>";
var emailFlowPage = "<div class=\"page\" id=\"page-emailflow\"><div class=\"flow-page\"><h1 class=\"flow-title\">&#x1F4E7; Auto Review Email — How It Works</h1><p class=\"flow-subtitle\">End-to-end flow from order fulfillment to customer review submission</p><div class=\"flow-steps\"><div class=\"flow-step\"><div class=\"flow-icon flow-icon-shopify\">&#x2699;</div><div class=\"flow-body\"><div class=\"flow-step-title\">Step 1 — Merchant enables Auto Emails</div><span class=\"flow-tag tag-file\">app/routes/app._index.jsx</span><span class=\"flow-tag tag-db\">MerchantStore DB</span><p class=\"flow-step-desc\">In the Rizzz Reviews dashboard, the merchant clicks \"Enable auto emails\". This POSTs intent=toggle-email to the Remix action, which flips <code style=\"background:#f0eeff;padding:1px 5px;border-radius:3px;font-size:12px\">autoEmailEnabled = true</code> in the MerchantStore table. The merchant also sets the delay (3/5/7/14 days) in Settings.</p><div class=\"flow-settings-note\">&#x2699;&#xFE0F; Settings stored in SQLite via Prisma: <code>autoEmailEnabled: true</code> &nbsp;|&nbsp; <code>emailDelayDays: 7</code></div></div></div><div class=\"flow-step\"><div class=\"flow-icon flow-icon-shopify\">&#x1F6D2;</div><div class=\"flow-body\"><div class=\"flow-step-title\">Step 2 — Customer places order & it gets fulfilled</div><span class=\"flow-tag tag-webhook\">Shopify Webhook: ORDERS_FULFILLED</span><span class=\"flow-tag tag-file\">app/shopify.server.js</span><p class=\"flow-step-desc\">When a merchant marks an order as fulfilled in Shopify Admin (or it auto-fulfills), Shopify sends a signed HMAC webhook POST to <code style=\"background:#f0eeff;padding:1px 5px;border-radius:3px;font-size:12px\">/webhooks/orders-fulfilled</code>. The webhook is registered automatically in <code style=\"background:#f0eeff;padding:1px 5px;border-radius:3px;font-size:12px\">afterAuth</code> when the app is installed.</p><div class=\"flow-code\"><span class=\"cm\">// shopify.server.js — registered on install</span>\n<span class=\"kw\">ORDER_FULFILLED</span>: {\n  deliveryMethod: <span class=\"str\">\"Http\"</span>,\n  callbackUrl: <span class=\"str\">\"/webhooks/orders-fulfilled\"</span>\n}</div></div></div><div class=\"flow-step\"><div class=\"flow-icon flow-icon-node\">&#x26A1;</div><div class=\"flow-body\"><div class=\"flow-step-title\">Step 3 — Webhook handler validates & saves to DB</div><span class=\"flow-tag tag-file\">app/routes/webhooks.orders-fulfilled.jsx</span><span class=\"flow-tag tag-db\">ReviewRequest DB</span><p class=\"flow-step-desc\">The Remix action verifies the Shopify HMAC signature, checks that <code style=\"background:#f0eeff;padding:1px 5px;border-radius:3px;font-size:12px\">autoEmailEnabled === true</code>, extracts the customer email + product handles from the order payload, and creates a ReviewRequest record with status = \"pending\".</p><div class=\"flow-code\"><span class=\"cm\">// Guard check</span>\n<span class=\"kw\">if</span> (!merchant?.<span class=\"fn\">autoEmailEnabled</span>) {\n  <span class=\"kw\">return</span> <span class=\"str\">\"Auto emails disabled\"</span>;\n}\n\n<span class=\"cm\">// Save to ReviewRequest table</span>\n<span class=\"kw\">await</span> prisma.reviewRequest.<span class=\"fn\">create</span>({\n  data: { shopDomain, orderId, customerEmail,\n          productHandles, status: <span class=\"str\">\"pending\"</span> }\n});</div><div class=\"status-row\"><span class=\"status-pill sp-pending\">● pending — just created</span></div></div></div><div class=\"flow-step\"><div class=\"flow-icon flow-icon-api\">&#x1F310;</div><div class=\"flow-body\"><div class=\"flow-step-title\">Step 4 — Node app calls rizzz.online CI4 API to queue the email</div><span class=\"flow-tag tag-api\">POST /shopify/review-request</span><span class=\"flow-tag tag-file\">webhooks.orders-fulfilled.jsx</span><p class=\"flow-step-desc\">The Node app POSTs to the Rizzz CI4 backend with the customer details, product handles, and <code style=\"background:#f0eeff;padding:1px 5px;border-radius:3px;font-size:12px\">delay_days: 7</code>. The CI4 backend schedules the email to be sent after the configured delay. On success, the ReviewRequest status is updated to \"sent\".</p><div class=\"flow-code\"><span class=\"fn\">fetch</span>(<span class=\"str\">`${RIZZZ_API_URL}/shopify/review-request`</span>, {\n  method: <span class=\"str\">\"POST\"</span>,\n  body: JSON.<span class=\"fn\">stringify</span>({\n    shop_domain, order_id, customer_email,\n    customer_name, product_handles,\n    delay_days: <span class=\"num\">7</span>   <span class=\"cm\">// from MerchantStore.emailDelayDays</span>\n  })\n});</div><div class=\"status-row\"><span class=\"status-pill sp-sent\">● sent — CI4 accepted the request</span></div></div></div><div class=\"flow-step\"><div class=\"flow-icon flow-icon-email\">&#x23F0;</div><div class=\"flow-body\"><div class=\"flow-step-title\">Step 5 — CI4 backend waits N days, then sends the email</div><span class=\"flow-tag tag-api\">rizzz.online CI4 backend</span><p class=\"flow-step-desc\">The CI4 backend (on rizzz.online) holds the request in its queue. After <strong>emailDelayDays</strong> days (default 7), it sends a branded review request email to the customer. The email contains the product name, order number, a star-tap shortcut, and a CTA link to the Rizzz review form.</p><div class=\"flow-email-preview\"><div class=\"email-header\"><div class=\"email-logo\">Rizz<span>z</span> Reviews</div><div style=\"font-size:12px;opacity:.8;margin-top:4px\">How was your recent purchase?</div></div><div class=\"email-body\"><div class=\"email-hi\">Hi Priya! &#x1F44B;</div><p class=\"email-text\">You recently ordered from STRIDE Athletics. We'd love to hear what you think! Your review helps other shoppers make better decisions.</p><div class=\"email-product\"><div class=\"email-product-img\">&#x1F45F;</div><div><div class=\"email-product-name\">Air Max Pro Running Shoes</div><div class=\"email-product-order\">Order #1042 &nbsp;&#x2022;&nbsp; Delivered 28 Jun 2026</div></div></div><div style=\"font-size:13px;font-weight:600;margin-bottom:8px;color:#202223\">Tap a star to rate:</div><div class=\"email-stars\"><div class=\"email-star\">&#x2605;</div><div class=\"email-star\">&#x2605;</div><div class=\"email-star\">&#x2605;</div><div class=\"email-star\">&#x2605;</div><div class=\"email-star\">&#x2605;</div></div><a href=\"#\" class=\"email-cta\">Write a Full Review on Rizzz &#x2197;</a><p style=\"font-size:12px;color:#aaa;text-align:center\">Takes less than 2 minutes</p></div><div class=\"email-footer\">Sent by Rizzz Reviews on behalf of STRIDE Athletics &nbsp;&#x2022;&nbsp; <a href=\"#\" style=\"color:#7F77DD\">Unsubscribe</a></div></div></div></div><div class=\"flow-step\"><div class=\"flow-icon flow-icon-customer\">&#x1F464;</div><div class=\"flow-body\"><div class=\"flow-step-title\">Step 6 — Customer clicks the email & submits a review</div><span class=\"flow-tag tag-api\">rizzz.online/product/{handle}</span><p class=\"flow-step-desc\">The customer clicks \"Write a Full Review on Rizzz\" → lands on the Rizzz review form (pre-filled with product + order context) → submits their rating, title, and review body. The review is stored in the Rizzz CI4 database.</p></div></div><div class=\"flow-step\"><div class=\"flow-icon flow-icon-rizzz\">&#x2B50;</div><div class=\"flow-body\"><div class=\"flow-step-title\">Step 7 — Review appears in the widget on the product page</div><span class=\"flow-tag tag-api\">GET /reviews/{handle}</span><span class=\"flow-tag tag-file\">public/widget/rizzz-widget.js</span><p class=\"flow-step-desc\">The next time any customer visits the product page, <code style=\"background:#f0eeff;padding:1px 5px;border-radius:3px;font-size:12px\">rizzz-widget.js</code> fetches reviews from <code style=\"background:#f0eeff;padding:1px 5px;border-radius:3px;font-size:12px\">GET /api/reviews/{handle}?shop=...</code> and renders the new review with a ✓ Verified badge. The merchant dashboard stats (total reviews, average rating) also update.</p><div class=\"status-row\"><span class=\"status-pill sp-reviewed\">● reviewed — final state in ReviewRequest table</span></div></div></div></div></div></div>";
